<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>1st Floor - WCC SCAN Campus Directory</title>
    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <style>
        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
        }
        .floor-container {
            width: 100vw;
            height: 100vh;
            display: flex;
            flex-direction: column;
            padding: 1rem 1rem 1rem 7rem;
            box-sizing: border-box;
        }
        .svg-wrapper {
            flex: 1;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }
        .svg-wrapper svg {
            max-width: 95%;
            max-height: 90%;
            width: auto;
            height: auto;
        }
    </style>
</head>
<body style="background: linear-gradient(90deg, #164D30 0%, #185336 60%, #369976 100%);">
    <!-- Floor Navigator Component -->
    <x-floor-navigator :currentFloor="1" />

    <!-- Main Content -->
    <div class="floor-container">
        <!-- Header -->
        <div class="text-center mb-4">
            <h1 class="text-2xl font-bold text-white mb-1">1st Floor</h1>
            <p class="text-sm text-white/70">WCC SCAN Campus Directory</p>
        </div>

        <!-- SVG Container -->
